        "css": ".mockup-component--v2-header{display:flow-root;width:1280px;max-width:100%;}\n.mockup-component--v2-header,.mockup-component--v2-header *{box-sizing:border-box}\n.mockup-component--v2-header{color:#262626;font-family:\"Apple SD Gothic Neo\",\"Malgun Gothic\",sans-serif}\n.mockup-component--v2-header{font-size:18px;line-height:1.7}\n.mockup-component--v2-header header{padding:0 64px;height:100px;border-bottom:1px solid #aaa;display:flex;align-items:center;justify-content:space-between}\n.mockup-component--v2-header .logo{font-size:32px;letter-spacing:3px}\n.mockup-component--v2-header nav{display:flex;align-items:center;gap:24px}\n.mockup-component--v2-header button{font:inherit;border:1px solid #555;background:white;color:#262626;opacity:1;padding:13px 25px;cursor:default}\n.mockup-component--v2-header nav button{padding:0;border:0;font-size:15px}\n.mockup-component--v2-header section{padding:80px 64px;border-bottom:1px solid #aaa}\n.mockup-component--v2-header h1,.mockup-component--v2-header h2,.mockup-component--v2-header h3,.mockup-component--v2-header p{margin:0}\n.mockup-component--v2-header h1{font-size:68px;line-height:1.22;letter-spacing:-2.5px;margin:24px 0}\n.mockup-component--v2-header h2{font-size:48px;line-height:1.3;letter-spacing:-1.6px}\n.mockup-component--v2-header h3{font-size:25px;line-height:1.4;margin:16px 0 12px}\n.mockup-component--v2-header p{color:#555;font-size:19px}\n.mockup-component--v2-header .eyebrow{font-size:14px;letter-spacing:2px;display:block;margin-bottom:20px}\n.mockup-component--v2-header .actions{display:flex;gap:14px;margin-top:30px}\n.mockup-component--v2-header .hero{padding-top:60px}\n.mockup-component--v2-header .hero-head{display:flex;align-items:flex-end;justify-content:space-between;gap:40px;margin-bottom:42px}\n.mockup-component--v2-header .hero-head p{max-width:400px;margin-bottom:12px}\n.mockup-component--v2-header .hero-wordmark{font-size:100px;letter-spacing:12px;line-height:1;font-weight:700;color:#444}\n.mockup-component--v2-header .placeholder{position:relative;display:flex;align-items:center;justify-content:center;text-align:center;height:280px;border:1px solid #999;background:#f3f3f3;overflow:hidden}\n.mockup-component--v2-header .placeholder svg{position:absolute;inset:0;width:100%;height:100%;stroke:#c7c7c7;stroke-width:.3;fill:none}\n.mockup-component--v2-header .placeholder span{position:relative;background:#f3f3f3;padding:12px 22px;font-size:18px;max-width:90%}\n.mockup-component--v2-header .placeholder small{display:block;font-size:14px;color:#777;margin-top:8px}\n.mockup-component--v2-header .hero .placeholder{height:340px}\n.mockup-component--v2-header .intro{display:flex;justify-content:space-between;align-items:flex-end;gap:70px;margin-bottom:46px}\n.mockup-component--v2-header .intro p{max-width:440px}\n.mockup-component--v2-header .three{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}\n.mockup-component--v2-header .capability p{font-size:17px}\n.mockup-component--v2-header .capability .eyebrow{margin:24px 0 0}\n.mockup-component--v2-header .applications{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:46px}\n.mockup-component--v2-header .application{border:1px solid #aaa;display:flex;flex-direction:column}\n.mockup-component--v2-header .application .placeholder{border:0;border-bottom:1px solid #aaa;height:200px}\n.mockup-component--v2-header .application .text{padding:26px 18px;display:flex;flex-direction:column;flex:1}\n.mockup-component--v2-header .application h3{margin:0 0 15px}\n.mockup-component--v2-header .application p{font-size:16px;line-height:1.7;letter-spacing:-.4px;flex:1}\n.mockup-component--v2-header .application button{margin-top:25px;align-self:flex-start}\n.mockup-component--v2-header .scope-line{margin-top:35px;padding-top:24px;border-top:1px solid #ccc}\n.mockup-component--v2-header .global-title{font-size:62px;line-height:1.15;letter-spacing:-1.5px;margin-bottom:30px}\n.mockup-component--v2-header .global-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:46px;margin-top:44px}\n.mockup-component--v2-header .global-grid .placeholder{height:350px}\n.mockup-component--v2-header .global-grid h3{font-size:30px}\n.mockup-component--v2-header .note{font-size:15px;margin-top:24px}\n.mockup-component--v2-header .contact{text-align:center;padding:100px 64px}\n.mockup-component--v2-header .contact h2{font-size:56px;margin-bottom:25px}\n.mockup-component--v2-header .contact .actions{justify-content:center}\n.mockup-component--v2-header footer{padding:42px 64px;font-size:14px;color:#555}\n.mockup-component--v2-header footer .row{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}\n.mockup-component--v2-header footer p{font-size:14px}\n.mockup-component--v2-header footer button{padding:0;border:0;margin-left:25px;font-size:14px}\n.mockup-component--v2-header .localization-list{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:14px 24px;margin:28px 0 0;padding:0}\n.mockup-component--v2-header .localization-list li{display:flex;align-items:center;gap:12px;font-size:17px;white-space:nowrap}\n.mockup-component--v2-header .localization-list li::before{content:\"\";display:block;width:14px;height:14px;border-left:2px solid #888;border-bottom:2px solid #888;flex:none}\n.mockup-component--v2-header h1,.mockup-component--v2-header h2,.mockup-component--v2-header h3,.mockup-component--v2-header p,.mockup-component--v2-header .placeholder span{word-break:keep-all;overflow-wrap:break-word}\n.mockup-component--v2-header h1,.mockup-component--v2-header h2,.mockup-component--v2-header h3{text-wrap:wrap}\n.mockup-component--v2-header button,.mockup-component--v2-header .eyebrow{white-space:nowrap}\n.mockup-component--v2-header .placeholder span{font-size:16px}\n.mockup-component--v2-header .placeholder small{line-height:1.6}\n.mockup-component--v2-header .hero-head{display:grid;grid-template-columns:1.35fr 1fr;gap:48px}\n.mockup-component--v2-header .hero-head h1{font-size:62px}\n.mockup-component--v2-header .hero-head p{max-width:none;font-size:18px;line-height:1.8}\n.mockup-component--v2-header .hero-head .actions{gap:10px}\n.mockup-component--v2-header .hero-head button{padding:12px 18px;font-size:17px}\n.mockup-component--v2-header .intro{display:grid;grid-template-columns:1.2fr 1fr;gap:48px}\n.mockup-component--v2-header .intro h2{font-size:44px}\n.mockup-component--v2-header .intro p{max-width:none}\n.mockup-component--v2-header .application h3{font-size:22px;white-space:nowrap;letter-spacing:-.6px}\n.mockup-component--v2-header .capability h3{font-size:23px;white-space:nowrap;letter-spacing:-.5px}\n.mockup-component--v2-header .global-grid{grid-template-columns:1fr 1fr;gap:40px}\n.mockup-component--v2-header .global-grid h3{font-size:28px;line-height:1.5}\n.mockup-component--v2-header h2{white-space:nowrap}\n.mockup-component--v2-header .intro{display:block}\n.mockup-component--v2-header .intro p{max-width:920px;margin-top:24px}\n.mockup-component--v2-header .global-subtitle{font-size:28px;white-space:nowrap;margin:0}\n.mockup-component--v2-header .contact h2{font-size:48px}\n.mockup-component--v2-header .hero-head{grid-template-columns:1.1fr 1fr;gap:36px}\n.mockup-component--v2-header .hero-head h1{font-size:58px}\n.mockup-component--v2-header .hero-head p{font-size:17px;letter-spacing:-.35px}\n.mockup-component--v2-header .contact{padding:64px}\n.mockup-component--v2-header .contact h2{font-size:34px;margin:0 0 16px}\n.mockup-component--v2-header .contact p{font-size:18px}\n.mockup-component--v2-header .contact .actions{margin-top:24px}\n.mockup-component--v2-header .intro .intro-single-line{max-width:none;white-space:nowrap;font-size:16px;letter-spacing:-.3px}\n.mockup-component--v2-header .application .brand-collaboration-copy{white-space:nowrap}"
