        "html": "\u003cdiv class=\"mockup-component--main-header\">\n\u003cheader>\u003cstrong class=\"logo\">VISD\u003c/strong>\u003cnav aria-label=\"메뉴 위치 목업\">\u003cbutton type=\"button\" disabled>솔루션\u003c/button>\u003cbutton type=\"button\" disabled>소프트웨어\u003c/button>\u003cbutton type=\"button\" disabled>하드웨어\u003c/button>\u003cbutton type=\"button\" disabled>도입 사례\u003c/button>\u003cbutton type=\"button\" disabled>회사 소개\u003c/button>\u003cbutton type=\"button\" disabled>문의하기\u003c/button>\u003cbutton type=\"button\" disabled>KO / EN\u003c/button>\u003c/nav>\u003c/header>\n\u003c/div>",
        "css": ".mockup-component--main-header{display:flow-root;width:1280px;max-width:100%;}\n.mockup-component--main-header,.mockup-component--main-header *{box-sizing:border-box}\n.mockup-component--main-header{color:#292929;font-family:\"Apple SD Gothic Neo\",\"Malgun Gothic\",sans-serif}\n.mockup-component--main-header{font-size:18px;line-height:1.65}\n.mockup-component--main-header header{height:100px;display:flex;align-items:center;justify-content:space-between;padding:0 64px;border-bottom:1px solid #aaa}\n.mockup-component--main-header nav{display:flex;align-items:center;gap:23px;font-size:16px}\n.mockup-component--main-header .logo{font-size:30px;letter-spacing:2px}\n.mockup-component--main-header button{font:inherit;color:#292929;opacity:1;background:#fff;border:1px solid #555;padding:12px 22px;cursor:default}\n.mockup-component--main-header nav button{border:0;padding:0}\n.mockup-component--main-header section{padding:64px;border-bottom:1px solid #aaa}\n.mockup-component--main-header h1{font-size:46px;line-height:1.35;letter-spacing:-1.7px;margin:12px 0 24px}\n.mockup-component--main-header h2{font-size:34px;line-height:1.4;letter-spacing:-1px;margin:8px 0 18px}\n.mockup-component--main-header h3{font-size:23px;line-height:1.45;margin:20px 0 12px}\n.mockup-component--main-header p{margin:0 0 24px;color:#505050}\n.mockup-component--main-header .eyebrow{font-size:13px;letter-spacing:1.3px;color:#666}\n.mockup-component--main-header .hero{display:grid;grid-template-columns:1.15fr 1fr;gap:44px;min-height:600px;align-items:center}\n.mockup-component--main-header .actions{display:flex;gap:12px;margin-top:30px}\n.mockup-component--main-header .placeholder{position:relative;height:240px;border:1px solid #999;background:#f5f5f5;display:flex;align-items:center;justify-content:center;text-align:center;overflow:hidden}\n.mockup-component--main-header .placeholder svg{position:absolute;inset:0;width:100%;height:100%;stroke:#ccc;stroke-width:.35;fill:none}\n.mockup-component--main-header .placeholder span{position:relative;background:#f5f5f5;padding:12px 18px;max-width:90%;font-size:18px}\n.mockup-component--main-header .placeholder small{display:block;font-size:14px;color:#666;margin-top:8px}\n.mockup-component--main-header .hero .placeholder{height:390px}\n.mockup-component--main-header .three{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:32px}\n.mockup-component--main-header .card{border:1px solid #aaa;padding:22px;display:flex;flex-direction:column}\n.mockup-component--main-header .card .placeholder{height:160px}\n.mockup-component--main-header .card p{font-size:17px;flex:1}\n.mockup-component--main-header .card button{align-self:flex-start}\n.mockup-component--main-header .four{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:30px}\n.mockup-component--main-header .scope{border:1px solid #aaa;padding:24px}\n.mockup-component--main-header .scope h3{margin:0 0 15px}\n.mockup-component--main-header .scope p{font-size:17px;margin:0}\n.mockup-component--main-header .two{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:34px}\n.mockup-component--main-header .two .placeholder{height:300px}\n.mockup-component--main-header .note{font-size:16px;margin:24px 0 0}\n.mockup-component--main-header .contact{text-align:center;padding:70px 64px}\n.mockup-component--main-header .contact .actions{justify-content:center}\n.mockup-component--main-header footer{padding:40px 64px;font-size:14px;color:#555;min-height:190px}\n.mockup-component--main-header footer .row{display:flex;justify-content:space-between;margin-bottom:20px}\n.mockup-component--main-header footer p{margin:4px 0}\n.mockup-component--main-header footer button{font-size:14px;border:0;padding:0;margin-left:20px}\n.mockup-component--main-header .localization-list{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:14px 24px;margin:28px 0 0;padding:0}\n.mockup-component--main-header .localization-list li{display:flex;align-items:center;gap:12px;font-size:17px;white-space:nowrap}\n.mockup-component--main-header .localization-list li::before{content:\"\";display:block;width:14px;height:14px;border-left:2px solid #888;border-bottom:2px solid #888;flex:none}\n.mockup-component--main-header h1,.mockup-component--main-header h2,.mockup-component--main-header h3,.mockup-component--main-header p,.mockup-component--main-header .placeholder span{word-break:keep-all;overflow-wrap:break-word}\n.mockup-component--main-header h1,.mockup-component--main-header h2,.mockup-component--main-header h3{text-wrap:wrap}\n.mockup-component--main-header button,.mockup-component--main-header .eyebrow{white-space:nowrap}\n.mockup-component--main-header .placeholder span{font-size:16px}\n.mockup-component--main-header .placeholder small{line-height:1.6}\n.mockup-component--main-header .card h3{font-size:21px;white-space:nowrap;letter-spacing:-.5px}\n.mockup-component--main-header .hero{grid-template-columns:1.2fr 1fr;gap:40px}\n.mockup-component--main-header .hero h1{font-size:44px}\n.mockup-component--main-header .hero p{font-size:18px;line-height:1.8}\n.mockup-component--main-header .two h3{font-size:25px;line-height:1.5}\n.mockup-component--main-header h2{white-space:nowrap}\n.mockup-component--main-header .hero p{font-size:17px;letter-spacing:-.3px}\n.mockup-component--main-header .two h3{font-size:23px;white-space:nowrap}\n.mockup-component--main-header .contact{padding:64px}\n.mockup-component--main-header .contact h2{font-size:34px;margin:0 0 16px}\n.mockup-component--main-header .contact p{font-size:18px}\n.mockup-component--main-header .contact .actions{margin-top:24px}"
